const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL = value => { try { const u = new URL(value); return ['https:','http:'].includes(u.protocol) ? u.href : '#'; } catch { return '#'; } };
const KEY = 'baseball-performance-hub.v1';
const INBOX = '~/Documents/Baseball Study Hub/Inbox';
const SECTIONS = {
  strength:{name:'Physical Preparation',short:'Physical preparation',description:'Build the physical qualities that support baseball: force, power, speed, and the capacity to repeat the work.',num:'01'},
  programming:{name:'Baseball Programming',short:'The training week',description:'Fit the training dose to the player, the season, and the baseball work already on the schedule.',num:'02'},
  science:{name:'Applied Baseball Sports Science',short:'Better questions, useful data',description:'Measure consistently, distinguish change from noise, and turn findings into a defensible next decision.',num:'03'},
  rehab:{name:'Rehab & Return to Baseball',short:'From tissue to performance',description:'Connect anatomy, clinical context, progressive loading, and return to the demands of baseball.',num:'04'}
};
let practice, graduate, reader, baseballCases, interview, study, shelf, review, resume;
let requestedStudy = null;
function applyStudyRequest(){const remembered=globalThis.history?.state?.studyMode;if(!requestedStudy&&remembered)requestedStudy={route:location.hash,mode:remembered};if(!requestedStudy||requestedStudy.route!==location.hash)return;const step=({theory:0,applied:1,review:2})[requestedStudy.mode];if(Number.isInteger(step)){if(location.hash.startsWith('#lesson/'))ui.step=step;if(location.hash.startsWith('#unit/'))graduate.setView(step);}requestedStudy=null;}
function openStudy(route,mode){requestedStudy={route,mode};const remember=()=>{try{history.replaceState({...history.state,studyMode:mode||null},'');}catch{}};if(location.hash===route){remember();applyStudyRequest();render();main.focus({preventScroll:true});}else{location.hash=route;remember();}}
let labCatalog=[];
let curriculum = {roles:[],competencies:[],sourceGroups:[],stages:[]};
let lessons = [], sources = [], lessonById = new Map(), sourceById = new Map();
let state = {version:1,lessons:{},lastLesson:null}, storageOK = true, sync = null;
let ui = {step:0,region:'all',caseOpen:false,recallOpen:false,visualOnly:false,hiddenGraphics:[]}, cleanupAnatomy = null, renderToken = 0;
const main = $('#main');
const record = id => state.lessons[id] || {answers:{},note:'',status:'new',recallChecked:false};
function save(){sync?.changed();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Progress could not be saved. Export a backup before closing.');}}
function update(id, patch){state.lessons[id]={...record(id),...patch};save();}
let toastTimer;
function toast(text){$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').textContent='';},4500);}
function paragraphs(text){return String(text??'').split(/\n\s*\n/).map(p=>`<p>${esc(p)}</p>`).join('');}
const isReviewed = id => record(id).status === 'reviewed' && (record(id).reviewedContentVersion || 1) >= (lessonById.get(id)?.contentVersion || 1);
const statusName = id => record(id).status === 'reviewed' && !isReviewed(id) ? 'New material to review' : ({new:'Not started',learning:'In progress',reviewed:'Reviewed'}[record(id).status]||'Not started');
function progressCounts(){let reviewed=0,answered=0,correct=0;for(const l of lessons){const r=record(l.id);if(isReviewed(l.id))reviewed++;l.questions.forEach((q,i)=>{const a=r.answers?.[i];if(a){answered++;if(a.choice===q.answer)correct++;}});}return {reviewed,answered,correct};}
function goto(route){if(location.hash===`#${route}`)render();else location.hash=route;}
function button(label,action,extra=''){return `<button class="button" data-action="${action}" ${extra}>${label}</button>`;}
const anatomyTabs=active=>`<nav class="anatomy-tabs" aria-label="Anatomy views"><a href="#joints" ${active==='joints'?'aria-current="page"':''}>Joints &amp; ROM</a><a href="#delivery" ${active==='delivery'?'aria-current="page"':''}>Pitching delivery</a><a href="#swing" ${active==='swing'?'aria-current="page"':''}>Hitting swing</a><a href="#anatomy/shoulder" ${active==='atlas'?'aria-current="page"':''}>3D anatomy</a></nav>`;
function heading(eyebrow,title,sub=''){return `<div class="page-heading"><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1>${sub?`<p class="lede">${esc(sub)}</p>`:''}</div>`;}
function activateNav(key){document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===key){a.setAttribute('aria-current','page');const g=a.closest?.('details');if(g)g.open=true;}else a.removeAttribute('aria-current');});$('#section-label').textContent=SECTIONS[key]?.name||({theory:'Theory',applied:'Applied',overview:'Your study week',practice:'Turn knowledge into a work sample',lab:'Turn knowledge into a work sample',resources:'Usable full-text alternatives',curriculum:'Prepare for the responsibilities of the role',overview:'Your learning fieldbook',anatomy:'Structure → function → baseball',library:'Your evidence and your learning'}[key])||'Baseball Performance';}
function fieldDiagram(){return `<svg viewBox="0 0 300 235" role="img" aria-label="Baseball demands: throwing, sprinting, and repeated position-specific efforts"><path d="M150 197 24 71Q150 -33 276 71Z" fill="#182c93" stroke="#7e8ce4" stroke-width="1"/><path d="M150 197 79 126 150 55 221 126Z" fill="#354bc1" stroke="#a5afeb" stroke-width="1"/><path d="M150 197 24 71M150 197 276 71" stroke="#e5e8fa" fill="none"/><path d="M150 197 221 126 150 55 79 126Z" fill="none" stroke="#e5e8fa" stroke-width="1"/><circle cx="150" cy="132" r="20" fill="#182c93"/><path d="M144 129h12v4h-12Z" fill="#ffffff"/><path d="M150 197 158 197 158 203 150 210 142 203 142 197Z" fill="#ffffff"/><g fill="#ffffff"><path d="m221 120 6 6-6 6-6-6Z"/><path d="m150 49 6 6-6 6-6-6Z"/><path d="m79 120 6 6-6 6-6-6Z"/></g><path d="M165 189 207 142" fill="none" stroke="#bac5ff" stroke-width="2" stroke-dasharray="4 4"/><path d="m198 145 9-3-2 9" fill="none" stroke="#bac5ff" stroke-width="2"/><path d="M150 146v34" stroke="#bac5ff" stroke-width="2" stroke-dasharray="4 4"/><g fill="#ffffff" font-family="sans-serif" font-size="9" text-anchor="middle"><text x="150" y="28">POSITION-SPECIFIC DEMANDS</text><text x="197" y="185">Sprint</text><text x="119" y="160">Throw</text></g></svg>`;}
function baseballMap(){const paths=[['#demands','Player demands','Pitching, hitting, catching, fielding and running.'],['#section/strength','Physical preparation','Strength, power, speed and capacity for baseball work.'],['#section/programming','Baseball programming','Annual plans, pitcher cycles, position players and travel.'],['#section/science','Applied baseball sports science','Collect useful data and defend the interpretation.'],['#section/rehab','Rehab & return to baseball','Tissue context, clinical restrictions and baseball re-exposure.'],['#joints','Anatomy Lab','Joint ranges of motion, 3D muscles, ligaments and joints, tied to the task.'],['#cases','Cases & season lab','Practice the next decision and write a staff handoff.'],['#library','Sources & study records','Read the evidence; save notes and revisit your reasoning.']];return `<div class="path-list baseball-map">${paths.map(([href,title,desc],i)=>`<a href="${href}" class="path-row"><span class="path-number">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${desc}</p></div><span aria-hidden="true">↗</span></a>`).join('')}</div>`;}
function overview(){return study.home();}
function lessonCard(l){return `<a class="lesson-card" href="#lesson/${encodeURIComponent(l.id)}"><span class="tag">${l.practicalAssignment?'In depth · ':''}${esc(l.region||SECTIONS[l.section].short)}</span><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p><div class="card-bottom"><span>${esc(l.minutes)} min · ${l.questions.length} decisions</span><span class="status ${isReviewed(l.id)?'reviewed':''}">${record(l.id).bookmark?'★ ':''}${statusName(l.id)} <span aria-hidden="true">↗</span></span></div></a>`;}
function sectionPage(key){const s=SECTIONS[key];if(!s)return notFound();let filtered=lessons.filter(l=>l.section===key&&(key!=='rehab'||ui.region==='all'||l.region===ui.region));return `<div class="section-intro"><div><span class="eyebrow">LEARNING PATH ${s.num}</span><h1>${s.name}</h1><p class="lede">${s.description}</p></div><div class="section-count">${lessons.filter(l=>l.section===key).length} lessons<br>Learn · apply · recall</div></div>${key==='rehab'?`<div class="filters" aria-label="Rehabilitation regions">${['all','elbow','shoulder','hamstring'].map(r=>`<button class="filter" aria-pressed="${ui.region===r}" data-action="region" data-region="${r}">${r==='all'?'All regions':r[0].toUpperCase()+r.slice(1)}</button>`).join('')}</div>`:''}<div class="lesson-grid">${filtered.map(lessonCard).join('')}</div>${["programming","science"].includes(key)?`<div class="notice"><strong>Go deeper with the eight-unit baseball study path.</strong><p>Build a portfolio through extended lessons, concept diagrams, interactive experiments and defended decisions.</p><a class="button primary" href="#course/${key==='programming'?'m06':'m07'}">Open the baseball study path →</a></div>`:''}${key==='rehab'?'<p><a class="button primary" href="#cases/rehab">Compare return-to-baseball pathways →</a></p><div class="notice">Study the full pathway: anatomy and mechanisms → rehabilitation → baseball performance. Cases are educational; clinical restrictions and staff responsibilities remain part of the decision.</div>':''}`;}
function visual(l){return `<figure class="visual"><span class="eyebrow">READ THE PICTURE</span><h3>${esc(l.visual.title)}</h3><ol>${l.visual.steps.map((s,i)=>`<li><span class="node" aria-hidden="true">${i+1}</span><div><b>${esc(s.label)}</b><p>${esc(s.detail)}</p></div></li>`).join('')}</ol><figcaption>${esc(l.visual.caption)}</figcaption></figure>`;}
function sourceLink(ref){const source=sourceById.get(ref.id);return `<p><a href="#source/${encodeURIComponent(ref.id)}">${esc(source?.title||ref.id)}</a><br><span class="small muted">${esc(ref.locator)}</span></p>`;}
function question(l,q,i){const a=record(l.id).answers?.[i];return `<div class="question" id="question-${i}"><fieldset><legend><span class="eyebrow">DECISION ${i+1} OF ${l.questions.length}</span>${esc(q.prompt)}</legend>${q.options.map((o,j)=>`<button class="choice ${a&&a.choice!==q.answer?'incorrect':''}" data-action="answer" data-question="${i}" data-choice="${j}" aria-pressed="${a?.choice===j}"><span aria-hidden="true">${String.fromCharCode(65+j)}</span><span>${esc(o.text)}</span></button>`).join('')}</fieldset>${a?`<div class="feedback ${a.choice!==q.answer?'incorrect':''}" role="status"><strong>${a.choice===q.answer?'Correct.':'Reconsider this choice.'}</strong><p>${esc(q.options[a.choice]?.feedback)}</p><a class="small" href="#source/${encodeURIComponent(q.sourceId)}">Check the evidence ↗</a></div>`:''}</div>`;}
function teachingGraphic(l,g,index){
 const key=l.id+'--'+g.id, hidden=(ui.hiddenGraphics||[]).includes(key), stem='assets/lesson-graphics/'+encodeURIComponent(key);
 return `<figure class="teaching-graphic" id="graphic-${esc(key)}" aria-labelledby="graphic-title-${esc(key)}"><div class="graphic-heading"><span class="eyebrow">PICTURE ${index+1} OF ${l.graphics.length}</span><h3 id="graphic-title-${esc(key)}">${esc(g.title)}</h3></div><div id="graphic-content-${esc(key)}" ${hidden?'hidden':''}><picture><source media="(max-width: 1100px)" srcset="${stem}.mobile.svg"><img class="concept-image" src="${stem}.svg" alt="${esc(g.alt)}" loading="lazy" decoding="async"></picture><div class="memory-cue"><span class="eyebrow">REMEMBER THE IDEA</span><strong>${esc(g.mnemonic.cue)}</strong><p>${esc(g.mnemonic.meaning)}</p></div></div>${hidden?'<div class="graphic-covered"><span aria-hidden="true">↻</span><p>Picture hidden. Rebuild the main idea from memory.</p></div>':''}<figcaption>${esc(g.caption)}${g.datasetNote?`<p class="small muted">${esc(g.datasetNote)}</p>`:''}</figcaption><div class="graphic-retrieval"><button class="button" id="graphic-toggle-${esc(key)}" data-action="graphic-cover" data-graphic="${esc(key)}" aria-expanded="${!hidden}" aria-controls="graphic-content-${esc(key)}">${hidden?'Show picture and cue':'Hide picture and test recall'}</button><p class="graphic-prompt"><strong>Explain or apply:</strong> ${esc(g.recall.prompt)}</p><details><summary>Check your explanation</summary>${paragraphs(g.recall.answer)}</details><details><summary>Text description and sources</summary>${paragraphs(g.alt)}${(g.sourceRefs||[]).map(sourceLink).join('')}<p class="small muted">Original teaching graphic and memory cue. The cue is a study aid, not a validated clinical or performance rule.</p><a class="small" href="${stem}.svg" download>Download this diagram ↓</a></details></div></figure>`;
}
function learnContent(l){
 const graphics=l.graphics||[];
 const modes=graphics.length?`<div class="learning-controls"><div role="group" aria-label="Reading view"><button class="filter" data-action="learning-view" data-view="full" aria-pressed="${!ui.visualOnly}">Full chapter</button><button class="filter" data-action="learning-view" data-view="visual" aria-pressed="${!!ui.visualOnly}">Visual recap · ${graphics.length} pictures</button></div><p class="small muted">Study the idea → explain the picture → apply it → return later.</p></div>`:'';
 if(ui.visualOnly&&graphics.length)return modes+`<div class="visual-recap-intro"><h2>Rebuild the chapter from its pictures.</h2><p>Read each cue, hide the diagram, and answer its prompt before checking. Use the full chapter when your explanation needs more detail.</p></div>`+graphics.map((g,i)=>teachingGraphic(l,g,i)).join('');
 const contents=l.body.length>5?`<details class="chapter-nav"><summary>Chapter contents · ${l.body.length} sections</summary><nav aria-label="Chapter contents">${l.body.map((b,i)=>`<button data-action="chapter" data-chapter="${i}">${esc(b.heading)}</button>`).join('')}</nav></details>`:'';
 return modes+contents+l.body.map((b,i)=>`<section><h2 id="chapter-${i}" tabindex="-1">${esc(b.heading)}</h2>${paragraphs(b.text)}${b.sourceRefs?.length?`<details class="section-evidence"><summary>Evidence for this section</summary>${b.sourceRefs.map(sourceLink).join('')}</details>`:''}</section>`+graphics.map((g,n)=>g.afterSection===i?teachingGraphic(l,g,n):'').join('')).join('')+(graphics.length?'':visual(l));
}
function lessonStep(l){const r=record(l.id);if(ui.step===0)return learnContent(l)+shelf.sections('lesson:'+l.id);
if(ui.step===1)return `<section class="case-box"><span class="eyebrow">A BASEBALL CASE</span><h2>Make the next decision.</h2>${paragraphs(l.case.scenario)}<p><strong>${esc(l.case.question)}</strong></p><button class="button" data-action="case" aria-expanded="${ui.caseOpen}">${ui.caseOpen?'Hide':'Reveal'} the reasoning</button>${ui.caseOpen?`<div class="reveal">${paragraphs(l.case.answer)}</div>`:''}</section>${l.questions.map((q,i)=>question(l,q,i)).join('')}${practicalAssignment(l)}<p class="small muted">Feedback explains the selected choice. Try again after reviewing the reasoning; your progress records the latest answer.</p>`;
if(ui.step===2)return `<span class="eyebrow">CLOSE THE LOOP</span><h2>Explain it without the notes.</h2><p>${esc(l.recall.prompt)}</p><label class="field-label" for="lesson-note">Your explanation or study notes</label><textarea id="lesson-note" maxlength="20000" placeholder="Use your own words. What would change your decision?">${esc(r.note)}</textarea><p class="small muted">Saved automatically in this browser. Include in an export to keep a backup.</p><button class="button" data-action="recall" aria-expanded="${ui.recallOpen}">${ui.recallOpen?'Hide':'Reveal'} the reference answer</button>${ui.recallOpen?`<div class="reveal">${paragraphs(l.recall.answer)}</div>`:''}<div class="notice"><strong>Check your explanation.</strong> Did you name the key idea, apply it to baseball, and keep the limitation?</div><div class="actions"><button class="button primary" data-action="review">${isReviewed(l.id)?'Reviewed — review again':'Mark this lesson reviewed'}</button>${isReviewed(l.id)?'<span class="small muted">Your own review rating, not a clinical competency assessment.</span>':''}</div>`;
return `<h2>Evidence behind this lesson</h2><p class="muted">Read the population, methods, and limits before transferring a finding to a player.</p><div class="notice warning"><strong>Keep this limit</strong><p style="margin:8px 0 0">${esc(l.limit)}</p></div><div class="source-list">${l.sources.map(ref=>{const s=sourceById.get(ref.id);return s?`<article class="source-card"><span class="tag">${esc(s.type)}</span><h3>${esc(s.title)}</h3><p>${esc(s.authors)} · ${esc(s.year)}</p><p><strong>Supporting location:</strong> ${esc(ref.locator)}</p><p><strong>Access:</strong> ${esc(s.access)}</p><div class="actions"><a href="#source/${encodeURIComponent(s.id)}" class="small">Source details</a>${s.privateReference?'<span class="small muted">Private reference</span>':`<a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener" class="small">Open original ↗</a>`}</div></article>`:'';}).join('')}</div>`;}
function lessonPage(l){if(!l)return notFound();const r=record(l.id);const steps=['Theory','Applied','Recall','Sources'];const idx=lessons.findIndex(x=>x.id===l.id);const next=lessons[idx+1];return `<div class="breadcrumb"><a href="#overview">Overview</a><span>/</span><a href="#section/${l.section}">${esc(SECTIONS[l.section].name)}</a>${l.region?`<span>/ ${esc(l.region)}</span>`:''}</div><span class="eyebrow">${esc(l.region||SECTIONS[l.section].short)}</span><h1 class="lesson-title">${esc(l.title)}</h1><p class="lede">${esc(l.subtitle)}</p><div class="lesson-meta"><span>${esc(l.minutes)} min</span><span>${l.questions.length} applied decisions</span>${l.graphics?.length?`<span>${l.graphics.length} concept graphics</span>`:''}<span>${statusName(l.id)}</span><button class="icon-toggle" data-action="bookmark" aria-pressed="${!!r.bookmark}" aria-label="${r.bookmark?'Remove bookmark':'Bookmark this chapter'}" title="${r.bookmark?'Remove bookmark':'Bookmark this chapter'}"><svg class="icon-bm" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M6.5 3.5h11a1 1 0 0 1 1 1v16l-6.5-4.2-6.5 4.2v-16a1 1 0 0 1 1-1z" fill="${r.bookmark?'currentColor':'none'}" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg></button></div><nav class="lesson-toolbar" aria-label="Lesson stages">${steps.map((name,i)=>`<button class="step-tab" data-action="step" data-step="${i}" ${ui.step===i?'aria-current="step"':''}>${i+1}. ${name}</button>`).join('')}</nav><div class="lesson-layout"><article class="reading" id="lesson-content">${lessonStep(l)}</article><aside class="lesson-aside"><div class="objectives"><h3>By the end, you can…</h3><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>${shelf.aside('lesson:'+l.id)}${l.region?`<p class="aside-note">Make the structure visible.</p><a class="button" href="#anatomy/${l.region}">Open ${esc(l.region)} anatomy ↗</a>`:''}<p class="aside-note">Use the pictures to explain the idea. Try the case before revealing the reasoning. Return later and rebuild the explanation from memory.</p></aside></div><div class="lesson-bottom"><div class="actions">${ui.step>0?button('← Previous stage','step',`data-step="${ui.step-1}"`):`<a href="#theory/${study.placement.get('#lesson/'+l.id)?.week.id||''}" class="button">← This week’s theory</a>`}${ui.step<3?`<button class="button primary" data-action="step" data-step="${ui.step+1}">Next: ${steps[ui.step+1]} →</button>`:''}</div></div>`;}

function practicalAssignment(l){
 const a=l.practicalAssignment;if(!a)return '';
 return `<section class="practical-assignment"><span class="eyebrow">PRODUCE A WORK SAMPLE</span><h2>${esc(a.title)}</h2>${paragraphs(a.brief)}<h3>Your deliverables</h3><ol>${a.deliverables.map(d=>`<li>${esc(d)}</li>`).join('')}</ol><label class="field-label" for="assignment-note">Draft your response</label><textarea id="assignment-note" maxlength="30000" placeholder="State the decision, the evidence, the missing information, and who owns the next action.">${esc(record(l.id).assignmentNote||'')}</textarea><p class="small muted">Saved in this browser and included in your progress and notes exports. This is a self-review exercise; it is not automatically graded.</p><details><summary>Review against the rubric</summary><dl>${a.rubric.map(r=>`<dt>${esc(r.criterion)}</dt><dd>${esc(r.strongResponse)}</dd>`).join('')}</dl></details><details><summary>Compare with a worked response</summary><div class="reveal">${paragraphs(a.modelResponse)}</div></details>${a.sourceRefs?.length?`<details><summary>Evidence for the assignment</summary>${a.sourceRefs.map(sourceLink).join('')}</details>`:''}</section>`;
}
function curriculumPage(){
 const c=curriculum, expanded=lessons.filter(l=>l.practicalAssignment).length;
 return `${heading('BASEBALL ROLE & COVERAGE MAP','Prepare for the baseball responsibility.','A common foundation, specialist pathways, and work samples shaped by your recent professional-baseball applications.')}<div class="notice"><strong>Development status:</strong> ${expanded} of ${lessons.length} core chapters now include extended teaching, questions and a practical assignment. The diagrams and memory cues support review. The Practice Lab now adds three programming cases, three downloadable data assignments, and three rehabilitation cases with seven progression decisions each. Two baseball study paths add 16 sequenced units and two integrated work samples in programming and measurement. The new decision cases address player tasks, season transitions and contrasting rehab pathways. Observed practical work and practitioner feedback remain essential; chapter completion does not establish professional qualification.</div><div class="actions"><a class="button primary" href="#theory/week-05">Baseball programming →</a><a class="button" href="#theory/week-02">Baseball testing →</a><a class="button" href="#library">Research source library</a><a class="button primary" href="#applied">Open Applied →</a></div>${baseballCoverage()}<section class="curriculum-section"><h2>The target roles</h2><p class="muted">Historical application requirements guide what to learn. These are not claims that the jobs remain open. Saved posting text and saved requirement summaries are distinguished.</p><div class="role-grid">${c.roles.map(r=>`<article class="role-card"><span class="eyebrow">${esc(r.organization)}</span><h3>${esc(r.title)}</h3><p class="small muted">${esc(r.requisition||'')} · ${esc(r.sourceStatus)}</p><ul>${r.duties.map(d=>`<li>${esc(d)}</li>`).join('')}</ul>${r.scopeNotes?`<p class="small scope-note">${esc(r.scopeNotes)}</p>`:''}</article>`).join('')}</div></section><section class="curriculum-section"><h2>The learning sequence</h2><div class="curriculum-stages">${c.stages.map((s,i)=>`<article><span class="path-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.scope)}</p><p class="small"><strong>Produce:</strong> ${esc(s.deliverable)}</p>${s.lessonIds?.length?`<div class="curriculum-lesson-links">${s.lessonIds.map(id=>`<a href="#lesson/${encodeURIComponent(id)}">${esc(lessonById.get(id)?.title||id)} →</a>`).join('')}</div>`:''}${s.developmentNote?`<p class="small muted">${esc(s.developmentNote)}</p>`:''}</div></article>`).join('')}</div></section><section class="curriculum-section"><h2>What you must be able to do</h2><p class="muted">Each competency needs teaching, deliberate practice, and a defensible work sample. Knowledge assessment does not replace supervised coaching or clinical practice.</p><div class="competency-list">${c.competencies.map((x,i)=>`<details><summary><span class="path-number">${String(i+1).padStart(2,'0')}</span>${esc(x.title)}</summary><p>${esc(x.description)}</p><p><strong>Work sample:</strong> ${esc(x.assessment)}</p><p class="small muted"><strong>Evidence to demonstrate:</strong> ${esc(x.evidenceNeeded)}</p><p class="small"><strong>Relevant roles:</strong> ${(x.roleIds||[]).map(id=>{const r=c.roles.find(r=>r.id===id);return esc(r?r.organization+' — '+r.title:id);}).join('; ')}</p></details>`).join('')}</div></section><section class="curriculum-section"><h2>The material behind the expansion</h2><div class="source-list">${c.sourceGroups.map(g=>`<article class="source-card"><span class="tag">${esc(g.role)}</span><h3>${esc(g.title)}</h3><p>${esc(g.coverage)}</p><p><strong>Review status:</strong> ${esc(g.reviewStatus)}</p><p><strong>Use:</strong> ${esc(g.use)}</p></article>`).join('')}</div><div class="notice">Source PDFs, extracted text, screenshots, internal names, and local file paths stay outside the hosted app. Team methods and commercial teaching frameworks are evaluated alongside research; their thresholds and example schedules are not presented as universal rules.</div></section>`;
}

function baseballCoverage(){return `<section class="curriculum-section"><h2>Coverage and the next questions</h2><div class="table-scroll"><table class="progress-table baseball-coverage"><thead><tr><th>Baseball responsibility</th><th>Available now</th><th>Still needs development or observation</th></tr></thead><tbody><tr><td>Connect physical qualities to the player task</td><td>Three illustrated cases on pitching, hitting/running and catching/fielding.</td><td>Broader pitch/hit biomechanics, observational video tasks and practical coaching review.</td></tr><tr><td>Plan through a professional season</td><td>Eight programming units, the earlier weekly labs and a six-episode linked season simulation.</td><td>Additional pitcher/catcher seasons, real delivery logs and feedback from baseball staff.</td></tr><tr><td>Interpret measurements</td><td>Eight testing units, three data labs and baseball task-metric cases.</td><td>Observed collection on actual devices and validation of local workflows.</td></tr><tr><td>Support return to baseball</td><td>Nine chapters, three progression labs and three new pathway-comparison cases.</td><td>Complete individualized protocols, other diagnoses and expert clinical review. New comparisons do not constitute complete extra treatment pathways.</td></tr><tr><td>Explain the anatomy</td><td>Seven regional 3D views, shoulder to ankle and foot, with muscles, ligaments and joints (164 structures), the joint ROM explorer with a picture of every movement, and phase-by-phase breakdowns of the pitching delivery and the hitting swing, with illustrations.</td><td>Nerves and verified attachment footprints. Cards still need practitioner review.</td></tr></tbody></table></div><p class="scope-note">This hub specializes in baseball. The broad S&C, sports science, AI and leadership curriculum is a separate project; it does not define this hub's completion target.</p></section>`;}
function sourceCard(s,expanded=false){return `<article class="source-card"><div class="source-meta"><span class="badge">${esc(s.type)}</span><span>${esc(s.year)}</span></div>${expanded?`<h1 class="source-title">${esc(s.title)}</h1>`:`<h3><a href="#source/${encodeURIComponent(s.id)}">${esc(s.title)}</a></h3>`}<p>${esc(s.authors)}</p><p><strong>Access:</strong> ${esc(s.access)}</p><details ${expanded?'open':''}><summary>Findings, population & limits</summary><dl><dt>Population / context</dt><dd>${esc(s.population)}</dd><dt>What it contributes</dt><dd>${esc(s.findings)}</dd><dt>Limitations</dt><dd>${esc(s.limitations)}</dd><dt>Supporting sections</dt><dd>${esc((s.locations||[]).join(' · '))}</dd><dt>Reuse / license</dt><dd>${esc(s.license)}</dd><dt>Source review</dt><dd>${esc(s.reviewed)}</dd></dl></details><div class="actions" style="margin-top:15px">${s.privateReference?'<span class="small muted">Private reference · original retained on your Mac</span>':`<a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener" class="small">Open original source ↗</a>`}</div></article>`;}
function libraryTabs(active){return `<nav class="section-tabs" aria-label="Library and progress"><a href="#library" ${active==='library'?'aria-current="page"':''}>Source library</a><a href="#bookshelf" ${active==='bookshelf'?'aria-current="page"':''}>Free textbooks</a><a href="#progress" ${active==='progress'?'aria-current="page"':''}>Study progress</a><a href="#resources" ${active==='resources'?'aria-current="page"':''}>Accessible alternatives</a><a href="#saved" ${active==='saved'?'aria-current="page"':''}>Saved reading</a><a href="#theory">Theory sequence</a></nav>`;}
function library(){return `${heading('EVIDENCE LIBRARY','Follow the source.','Research, clinical frameworks, foundations, and expert practice — with their context kept visible.')}${libraryTabs('library')}<div class="heading-row"><span class="small muted">${sources.length} cataloged references · Search using the field above</span><button class="button" data-action="download-catalog">Download catalog ↓</button></div><div class="notice">A source being available to read does not establish permission to redistribute it. This hub presents original teaching and links to the original material; private reference files stay outside the app.</div><div class="source-list">${sources.map(s=>sourceCard(s)).join('')}</div><a class="button" href="#resources">Explore accessible alternatives →</a>`;}
function sourcePage(id){const s=sourceById.get(id);if(!s)return notFound();const linked=lessons.filter(l=>l.sources.some(r=>r.id===id)),courseLinks=[...graduate.units.values()].filter(u=>u.sourceRefs.some(r=>r.id===id)),caseLinks=[...baseballCases.catalog.values()].filter(c=>c.sourceRefs.some(r=>r.id===id)||c.stages.some(st=>st.decision.sourceId===id||st.graphic.sourceRefs.some(r=>r.id===id)||st.teaching.some(t=>t.sourceRefs.some(r=>r.id===id))));return `<div class="breadcrumb"><a href="#library">Source library</a><span>/ Source details</span></div>${sourceCard(s,true)}<h2 style="margin-top:35px">Study it in context</h2><div class="lesson-grid">${linked.map(lessonCard).join('')}</div>${courseLinks.map(u=>`<p><a href="#unit/${u.id}">${esc(u.course.id.toUpperCase())} · ${esc(u.title)} →</a></p>`).join('')}${caseLinks.map(c=>`<p><a href="#case/${c.id}">Baseball case · ${esc(c.title)} →</a></p>`).join('')}${shelf.context(id)}${!linked.length&&!courseLinks.length&&!caseLinks.length&&!shelf.context(id)?'<p class="muted">Reference or book cross-reference. See the course reading guide and NSCA cross-reference for its role.</p>':''}`;}
function progress(){const p=progressCounts();return `${heading('YOUR LEARNING','Keep the useful work.','Track what you have studied and keep a portable copy of your notes and answers.')}${libraryTabs('progress')}<div class="stats-strip"><div class="stat"><strong>${p.reviewed}/${lessons.length}</strong><span>lessons reviewed</span></div><div class="stat"><strong>${p.answered}</strong><span>questions attempted</span></div><div class="stat"><strong>${p.correct}</strong><span>latest answers correct</span></div></div><div class="actions"><button class="button primary" data-action="export">Export progress ↓</button><button class="button" data-action="import">Import progress ↑</button><input hidden type="file" id="import-progress" accept="application/json,.json"><button class="button" data-action="export-notes">Export notes ↓</button></div>${sync?sync.slot():''}<div class="notice">Progress is saved in this browser for this website address. Unless sync is on, it does not move between browsers or devices, and it never moves between the local and hosted editions. Importing a valid backup replaces this hub’s study record. To move your existing local study record here, export it from the local hub, then import that file here. Your CPSS progress is separate. Review labels are self-assessments; question counts describe your latest attempts.</div><div class="table-scroll"><table class="progress-table"><thead><tr><th>Lesson</th><th>Status</th><th>Decisions</th><th>Notes</th></tr></thead><tbody>${lessons.map(l=>{const r=record(l.id),answered=l.questions.filter((q,i)=>r.answers?.[i]).length;return `<tr><td><a href="#lesson/${encodeURIComponent(l.id)}">${esc(l.title)}</a></td><td>${statusName(l.id)}</td><td>${answered}/${l.questions.length}</td><td>${r.note||r.assignmentNote?'Saved':'—'}</td></tr>`;}).join('')}</tbody></table></div>${graduate.meter()}<a class="button" href="#theory">Theory chapters →</a>${baseballCases.progress()}${practice.progress()}`;}
function bookmarks(){const list=lessons.filter(l=>record(l.id).bookmark);return `${heading('SAVED FOR LATER','Your bookmarks.','Keep a short list of ideas to revisit.')}${libraryTabs('bookmarks')}<div class="lesson-grid">${list.map(lessonCard).join('')}</div>${!list.length?'<div class="empty">Open any lesson and select Bookmark to save it here.</div>':''}`;}
function about(){return `${heading('OPEN EDITION','A place to understand baseball performance.')}<div class="about-content"><h2>How to use the hub</h2><ol><li><strong>Theory:</strong> read the explanation and its three concept diagrams. Use Visual recap to review the pictures on their own, then hide each picture and explain it before checking.</li><li><strong>Applied:</strong> make a decision before revealing the case reasoning.</li><li><strong>Recall:</strong> explain the idea in your own words, then check and correct it.</li><li><strong>Sources:</strong> inspect the population, limitations, and original evidence.</li></ol><h2>What the core chapters cover</h2><p>College and professional baseball, with pitchers and position players. Rehabilitation covers elbow, shoulder, and hamstrings. Sources from other sports are labeled; clinical examples do not replace an athlete’s individual care plan.</p><h2>What the anatomy can show</h2><p>Z-Anatomy meshes (built on BodyParts3D) show static relationships between bones, muscles, ligaments and joint capsules in seven regions. The reduced-resolution models are not a throwing simulation, injury diagnosis, or a validated map of attachment footprints. The Anatomy Lab states where a structure is unavailable.</p><h2>Your study record stays in this browser</h2><p>The hosted edition uses owner-only Site access and requires sign-in. Notes, answers, bookmarks, and review progress are stored in this browser; signing in does not sync them. The hub includes no analytics or automatic file uploads. Export your progress before changing browsers, moving between the local and hosted editions, or clearing site data. Original private references and the Inbox are excluded from the hosted application.</p><h2>Source and content review</h2><p>Lessons are original educational syntheses, with source review dated October 12, 2026. The rehabilitation Practice Lab and baseball decision cases were added October 13, 2026 using the cited source reviews. The chapters, baseball study paths and cases have not undergone independent practitioner, clinical or anatomical expert review. Clinical frameworks, observational findings, expert practice, and hypothetical cases are identified as such.</p><p>The baseball role map connects study to responsibilities from the target application roles. Supplied materials are privately cataloged; the curriculum page distinguishes material already expanded from the work still planned.</p></div>`;}
function searchPage(query){const term=query.toLowerCase().trim();const matches=lessons.filter(l=>[l.title,l.subtitle,l.region,...l.tags,...l.body.map(b=>b.text)].join(' ').toLowerCase().includes(term));const sm=sources.filter(s=>[s.title,s.authors,s.type,s.findings].join(' ').toLowerCase().includes(term));return `${heading('SEARCH',`Results for “${query}”`,`${matches.length} foundation chapters · ${(graduate.search(term).match(/class="search-result"/g)||[]).length} in-depth chapters · ${sm.length} sources · ${(baseballCases.search(term).match(/class="search-result"/g)||[]).length} baseball cases · ${(practice.search(term).match(/class="search-result"/g)||[]).length} practice labs`)}<div class="search-results"><div id="anatomy-search" class="search-results"></div>${interview.search(term)}${baseballCases.search(term)}${graduate.search(term)}${practice.search(term)}${matches.map(l=>`<a class="search-result" href="#lesson/${encodeURIComponent(l.id)}"><span class="tag">${esc(SECTIONS[l.section].name)}</span><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p></a>`).join('')}${sm.map(s=>`<a class="search-result" href="#source/${encodeURIComponent(s.id)}"><span class="tag">SOURCE · ${esc(s.type)}</span><h3>${esc(s.title)}</h3><p>${esc(s.authors)} · ${esc(s.year)}</p></a>`).join('')}</div>${!matches.length&&!sm.length&&!practice.search(term)&&!graduate.search(term)&&!baseballCases.search(term)&&!interview.search(term)?'<div class="empty" id="search-empty">No matches. Try a broader term such as elbow, sprint, load, or reliability.</div>':''}`;}
function notFound(){return `${heading('NOT FOUND','That page is not in this edition.')}<a class="button primary" href="#overview">Return to overview</a>`;}
async function render(){const token=++renderToken;if(cleanupAnatomy){cleanupAnatomy();cleanupAnatomy=null;}const parts=(location.hash.slice(1)||'overview').split('/');let type=parts[0],id;try{id=decodeURIComponent(parts.slice(1).join('/'));}catch{id='';}let nav=type,html='';
if(type==='overview')html=overview();else if(type==='week'){nav='overview';html=study.weekPage(id);}else if(type==='theory'||type==='applied'){html=study.directory(type,id);}else if(type==='project'){nav='applied';html=graduate.projectPage(id);}else if(type==='section'){nav='theory';html=study.directory('theory');}else if(type==='lesson'){const l=lessonById.get(id);nav=ui.step===1?'applied':'theory';html=lessonPage(l);}else if(type==='demands'){nav='applied';html=study.directory('applied');}else if(type==='cases'){nav='applied';html=study.directory('applied');}else if(type==='case'){nav='applied';html=baseballCases.page(id);}else if(type==='interview'){nav='interview';html=id?interview.page(id):interview.home();}else if(type==='courses'){nav='theory';html=study.directory('theory');}else if(type==='course'){nav='courses';html=graduate.coursePage(id);}else if(type==='unit'){nav=graduate.getView()===1?'applied':'theory';html=graduate.unitPage(id);}else if(type==='book-crosswalk'){nav='courses';html=graduate.bookPage();}else if(type==='saved'){html=reader.page();}else if(type==='review'){nav='review';html=`${heading('DAILY RECALL','Recall what you studied.','One short queue across chapters, joint ranges, the delivery, the swing and the 3D structures. Answer from memory, then rate yourself.')}<div id="review-host"><p class="muted">Loading today’s cards…</p></div>`;}else if(type==='practice'){nav='applied';html=study.directory('applied');}else if(type==='lab'){nav='applied';html=practice.page(id);}else if(type==='resources'){nav='library';html=practice.resourcePage();}else if(type==='curriculum')html=curriculumPage();else if(type==='library')html=library();else if(type==='bookshelf'){nav='library';html=shelf.page(libraryTabs('bookshelf'));}else if(type==='progress'){nav='progress';html=progress();}else if(type==='bookmarks'){nav='saved';html=reader.page();}else if(type==='source'){nav='library';html=sourcePage(id);}else if(type==='about'){nav='overview';html=about();}else if(type==='search'){html=searchPage(id);$('#search').value=id;}else if(type==='delivery'){nav='anatomy';html=`${heading('ANATOMY LAB','The pitching delivery, phase by phase.','Each phase: what the joints do, which muscles work, which tissue takes the load, and what it means for training.')}${anatomyTabs('delivery')}<div id="delivery-host"><p class="muted">Loading the delivery…</p></div>`;}else if(type==='swing'){nav='anatomy';html=`${heading('ANATOMY LAB','The hitting swing, phase by phase.','Each phase: what the body does, which muscles work, which tissue takes the load, and what it means for training.')}${anatomyTabs('swing')}<div id="swing-host"><p class="muted">Loading the swing…</p></div>`;}else if(type==='joints'){nav='anatomy';html=`${heading('ANATOMY LAB','Joints and their range of motion.','Pick a joint, tap a movement, and see its normal range with the source. Baseball adaptations sit next to the norm.')}${anatomyTabs('joints')}<div id="joints-host"><p class="muted">Loading joints…</p></div>`;}else if(type==='anatomy'){html=`${heading('ANATOMY LAB','Explore the structure.','Pick a region, turn layers on and off, and read how each muscle, ligament and joint matters in baseball.')}${anatomyTabs('atlas')}<div id="anatomy-host"><p class="muted">Loading the anatomy viewer…</p></div>`;}else html=notFound();
if(['lesson','unit','case','lab'].includes(type)){const route='#'+type+'/'+id;html=study.trail(route)+html.replace(/^<div class="breadcrumb">[\s\S]*?<\/div>/,'')+study.after(route);}main.setAttribute('data-study-area',nav);
main.innerHTML=(!storageOK?'<div class="notice warning">Browser storage is unavailable. Use Export progress to keep your work.</div>':'')+html;activateNav(nav);reader.afterRender();resume.afterRender();sync?.paint();if(type==='overview'){const slot=$('#resume-today');if(slot)slot.innerHTML=resume.todayHTML();review.fillToday($('#recall-today')).catch(e=>console.error(e));}review.badge($('#nav-recall-count')).catch(()=>{});if(type==='bookshelf')shelf.bind(main);document.title=`${type==='lesson'?(lessonById.get(id)?.title||'Lesson'):type==='case'?(baseballCases.catalog.get(id)?.title||'Baseball Case'):type==='interview'?(interview.catalog.get(id)?.title||'Case Studies'):type==='unit'?(graduate.units.get(id)?.title||'Unit'):type==='course'?(graduate.courses.find(c=>c.id===id)?.title||'Course'):SECTIONS[nav]?.name||({theory:'Theory',applied:'Applied',week:'Your Study Week',project:'Final Work Sample',courses:'Theory',course:'Baseball Study Path',unit:'Baseball Study Unit',demands:'Player Demands',cases:'Baseball Decision Lab',case:'Baseball Case',saved:'Saved Reading','book-crosswalk':'NSCA Book Cross-reference',practice:'Practice Lab',lab:'Practice Lab',resources:'Accessible alternatives',curriculum:'Baseball roles & coverage',overview:'Study Hub',anatomy:'Anatomy Lab',joints:'Joints & ROM',review:'Daily Recall',delivery:'Pitching Delivery',library:'Sources & Progress',bookshelf:'Free Textbook Shelf',progress:'Study Progress'}[type]||'Study Hub')} · Baseball Performance`;
if(type==='swing'){try{const {mountSwing}=await import('./delivery.js');if(token!==renderToken)return;const cleanup=await mountSwing($('#swing-host'),{phase:id||'acceleration',onChange:ph=>history.replaceState(null,'','#swing/'+ph)});if(token!==renderToken)cleanup();else cleanupAnatomy=cleanup;}catch(e){if(token===renderToken)$('#swing-host').innerHTML='<div class="notice warning"><h2>The swing breakdown could not load.</h2><p>Reload this page.</p></div>';console.error(e);}}
if(type==='delivery'){try{const {mountDelivery}=await import('./delivery.js');if(token!==renderToken)return;const cleanup=await mountDelivery($('#delivery-host'),{phase:id||'cocking',onChange:ph=>history.replaceState(null,'','#delivery/'+ph)});if(token!==renderToken)cleanup();else cleanupAnatomy=cleanup;}catch(e){if(token===renderToken)$('#delivery-host').innerHTML='<div class="notice warning"><h2>The delivery breakdown could not load.</h2><p>Reload this page.</p></div>';console.error(e);}}
if(type==='review'){try{const cleanup=await review.mount($('#review-host'),{onChange:()=>review.badge($('#nav-recall-count')).catch(()=>{})});if(token!==renderToken)cleanup();else cleanupAnatomy=cleanup;}catch(e){console.error(e);}}
if(type==='search'&&id){import('./anatomy-search.js').then(m=>token===renderToken?m.fillAnatomySearch($('#anatomy-search'),id):0).then(n=>{if(n&&token===renderToken)$('#search-empty')?.remove();}).catch(e=>console.error(e));}
if(type==='joints'){try{const {mountJoints}=await import('./joints.js');if(token!==renderToken)return;const cleanup=await mountJoints($('#joints-host'),{joint:id,onChange:j=>history.replaceState(null,'','#joints/'+j)});if(token!==renderToken)cleanup();else cleanupAnatomy=cleanup;}catch(e){if(token===renderToken)$('#joints-host').innerHTML='<div class="notice warning"><h2>The joint explorer could not load.</h2><p>Reload this page.</p></div>';console.error(e);}}
if(type==='anatomy'){try{const {mountAnatomy}=await import('./anatomy.js');if(token!==renderToken)return;const cleanup=await mountAnatomy($('#anatomy-host'),{region:['shoulder','scapula','elbow','trunk','hip','hamstring','ankle'].includes(id.split('/')[0])?id.split('/')[0]:'shoulder',select:id.split('/')[1]||'',onNavigateLesson:region=>{const l=lessons.find(l=>l.region===region);if(l)goto('lesson/'+encodeURIComponent(l.id));},onChange:r=>history.replaceState(null,'','#anatomy/'+r)});if(token!==renderToken){if(typeof cleanup==='function')cleanup();}else cleanupAnatomy=typeof cleanup==='function'?cleanup:null;}catch(e){if(token===renderToken)$('#anatomy-host').innerHTML=`<div class="notice warning"><h2>The 3D viewer could not load.</h2><p>Your lessons remain available. Reload this page. If you are using the local edition, you can also reopen its launcher.</p><a href="#section/rehab">Read the rehabilitation lessons →</a></div>`;console.error(e);}}
}
function currentLesson(){let id;try{id=decodeURIComponent(location.hash.slice('#lesson/'.length));}catch{return null;}return location.hash.startsWith('#lesson/')?lessonById.get(id):null;}
function sanitizeProgress(data){if(!data||data.version!==1||!data.lessons||typeof data.lessons!=='object'||Array.isArray(data.lessons))throw new Error('Unsupported progress format.');const clean={version:1,lessons:{},practice:practice.sanitize(data.practice),baseballCases:baseballCases.sanitize(data.baseballCases),interview:interview.sanitize(data.interview),study:study.sanitize(data.study),graduate:graduate.sanitize(data.graduate),reader:reader.sanitize(data.reader),review:sanitizeReview(data.review),resume:sanitizeResume(data.resume,r=>resolveRoute(r).valid),lastLesson:lessonById.has(data.lastLesson)?data.lastLesson:null};for(const l of lessons){const input=data.lessons[l.id];if(!input||typeof input!=='object')continue;const answers={};l.questions.forEach((q,i)=>{const a=input.answers?.[i];if(a&&Number.isInteger(a.choice)&&a.choice>=0&&a.choice<q.options.length)answers[i]={choice:a.choice,attempts:Number.isInteger(a.attempts)?Math.max(1,Math.min(100000,a.attempts)):1};});clean.lessons[l.id]={status:['new','learning','reviewed'].includes(input.status)?input.status:'new',note:typeof input.note==='string'?input.note.slice(0,20000):'',assignmentNote:typeof input.assignmentNote==='string'?input.assignmentNote.slice(0,30000):'',reviewedContentVersion:Number.isInteger(input.reviewedContentVersion)?Math.max(1,Math.min(1000,input.reviewedContentVersion)):1,bookmark:input.bookmark===true,answers,lastViewed:typeof input.lastViewed==='string'?input.lastViewed:'',reviewedAt:typeof input.reviewedAt==='string'?input.reviewedAt:''};}return clean;}
function resolveRoute(route){const parts=String(route).replace(/^#/, '').split('/');let id;try{id=decodeURIComponent(parts.slice(1).join('/'));}catch{return {valid:false,title:''};}const type=parts[0];let title=null;if(['week','theory','applied'].includes(type)&&id)title=study?.weeks.find(w=>w.id===id)?.title;else if(type==='project')title=graduate?.courses.find(c=>c.id===id)?.project.title;else if(type==='case')title=baseballCases?.catalog.get(id)?.title;else if(type==='interview'&&id)title=interview?.catalog.get(id)?.title;else if(type==='cases'&&['season','rehab'].includes(id))title=id==='season'?'Season simulation':'Rehab comparisons';else if(type==='lesson')title=lessonById.get(id)?.title;else if(type==='unit')title=graduate?.units.get(id)?.title;else if(type==='course')title=graduate?.courses.find(c=>c.id===id)?.title;else if(type==='source')title=sourceById.get(id)?.title;else if(type==='lab')title=labCatalog.find(l=>l.id===id)?.title;else if(type==='section')title=SECTIONS[id]?.name;else if(type==='anatomy'&&['shoulder','scapula','elbow','trunk','hip','hamstring','ankle'].includes(id.split('/')[0]))title=id.split('/')[0]+' anatomy';else if(type==='delivery')title=id?id+' phase':'Pitching delivery';else if(type==='swing')title=id?'Swing: '+id:'Hitting swing';else if(type==='joints')title=id?id+' range of motion':'Joints & range of motion';else if(type==='search'&&id&&id.length<200)title='Search: '+id;else if(!id)title=({overview:'My study week',theory:'Theory',applied:'Applied',demands:'Player demands',cases:'Baseball decision lab',interview:'Case studies',courses:'Baseball study paths','book-crosswalk':'NSCA baseball cross-reference',saved:'Saved reading',bookmarks:'Saved reading',review:'Daily recall',practice:'Practice Lab',resources:'Accessible alternatives',curriculum:'Baseball roles & coverage',library:'Source library',bookshelf:'Free textbook shelf',progress:'Study progress',about:'About the hub'})[type];return {valid:typeof title==='string',title:title||''};}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
main.addEventListener('click',async e=>{if(study.click(e,render)||interview.click(e,render)||baseballCases.click(e,render)||graduate.click(e,render)||practice.click(e,render))return;const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,l=currentLesson();
if(action==='learning-view'){ui.visualOnly=b.dataset.view==='visual';render();$(`[data-action="learning-view"][data-view="${b.dataset.view}"]`)?.focus({preventScroll:true});return;}
if(action==='graphic-cover'){const key=b.dataset.graphic;const hidden=new Set(ui.hiddenGraphics||[]);if(hidden.has(key))hidden.delete(key);else hidden.add(key);ui.hiddenGraphics=[...hidden];render();document.getElementById('graphic-'+key)?.scrollIntoView({block:'start'});document.getElementById('graphic-toggle-'+key)?.focus({preventScroll:true});return;}
if(action==='chapter'){const target=document.getElementById('chapter-'+b.dataset.chapter);target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});return;}
if(action==='region'){ui.region=b.dataset.region;render();return;}
if(action==='copy-inbox'){try{await navigator.clipboard.writeText(INBOX);toast('Inbox folder path copied.');}catch{toast('Select and copy the folder path shown above.');}return;}
if(action==='import'){$('#import-progress').click();return;}
if(action==='export'){download('Baseball-Study-Progress.json',JSON.stringify({app:'baseball-performance-hub',version:1,exportedAt:new Date().toISOString(),data:state},null,2),'application/json');toast('Progress backup exported.');return;}
if(action==='download-catalog'){download('Baseball-Source-Catalog.json',JSON.stringify(sources,null,1),'application/json');return;}if(action==='export-notes'){const notes=lessons.filter(l=>record(l.id).note||record(l.id).assignmentNote).map(l=>`## ${l.title}\n\n${record(l.id).note||''}${record(l.id).assignmentNote?'\n\n### Practical assignment\n\n'+record(l.id).assignmentNote:''}`).join('\n\n');download('Baseball-Study-Notes.md','# Baseball Performance — Study Notes\n\n'+(notes||'No lesson notes saved yet.')+'\n\n'+practice.exportNotes()+'\n\n'+graduate.exportNotes()+'\n\n'+reader.exportNotes()+'\n\n'+baseballCases.exportNotes()+'\n\n'+interview.exportNotes(),'text/markdown');return;}
if(!l)return;
const r=record(l.id);if(action==='step'){ui.step=Math.max(0,Math.min(3,Number(b.dataset.step)));render();main.scrollIntoView({block:'start'});main.focus({preventScroll:true});return;}
const refocus=()=>$(`[data-action="${action}"]`)?.focus({preventScroll:true});
if(action==='bookmark'){update(l.id,{bookmark:!r.bookmark});render();refocus();return;}
if(action==='case'){ui.caseOpen=!ui.caseOpen;render();refocus();return;}
if(action==='recall'){ui.recallOpen=!ui.recallOpen;render();refocus();return;}
if(action==='review'){update(l.id,{status:'reviewed',reviewedAt:new Date().toISOString(),reviewedContentVersion:l.contentVersion||1});render();refocus();toast('Lesson marked reviewed. Revisit it later from memory.');return;}
if(action==='answer'){const i=Number(b.dataset.question),choice=Number(b.dataset.choice);if(!l.questions[i]||!l.questions[i].options[choice])return;const answers={...r.answers,[i]:{choice,attempts:(r.answers?.[i]?.attempts||0)+1}};update(l.id,{answers});const y=scrollY;render();window.scrollTo(0,y);const focus=$(`[data-action="answer"][data-question="${i}"][data-choice="${choice}"]`);focus?.focus({preventScroll:true});}
});
main.addEventListener('input',e=>{if(interview.input(e)||baseballCases.input(e)||graduate.input(e)){reader.afterRender();return;}if(practice.input(e))return;const l=currentLesson();if(!l)return;if(e.target.id==='lesson-note')update(l.id,{note:e.target.value});if(e.target.id==='assignment-note')update(l.id,{assignmentNote:e.target.value});});
main.addEventListener('change',async e=>{if(study.change(e)||practice.change(e,render))return;if(e.target.id!=='import-progress')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('Backup is too large.');const envelope=JSON.parse(await file.text());if(envelope?.app!=='baseball-performance-hub'||envelope.version!==1)throw new Error('This is not a Baseball Performance progress backup.');const clean=sanitizeProgress(envelope.data);state=clean;save();render();toast('Your progress and notes have been imported.');}catch(err){toast(`Import failed: ${err.message}`);e.target.value='';}});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();const value=$('#search').value.trim();if(value)goto('search/'+encodeURIComponent(value));else goto('overview');});
$('#nav-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#nav-toggle').setAttribute('aria-expanded',String(open));});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}});
function routeChanged(){practice.reset();graduate.reset();baseballCases.reset();clearTimeout(toastTimer);$('#toast').textContent='';if(!location.hash.startsWith('#search/'))$('#search').value='';ui={...ui,step:0,caseOpen:false,recallOpen:false,visualOnly:false,hiddenGraphics:[]};$('#navigation').classList.remove('open');$('#nav-toggle').setAttribute('aria-expanded','false');const l=currentLesson();if(l){const r=record(l.id);state.lastLesson=l.id;update(l.id,{lastViewed:new Date().toISOString(),status:r.status==='new'?'learning':r.status});}study.visit(location.hash||'#overview');applyStudyRequest();render();window.scrollTo(0,0);main.focus({preventScroll:true});}
async function init(){try{const names=['performance-lessons','rehab-lessons','performance-sources','rehab-sources','curriculum','programming-labs','analysis-labs','resource-alternatives','rehab-labs','graduate-programming','graduate-science','graduate-sources','book-crosswalk','book-sources','baseball-demands','baseball-season','baseball-rehab-pathways','baseball-sources','study-plan','interview-cases','free-books'];const data=await Promise.all(names.map(async n=>{const response=await fetch(`data/${n}.json`);if(!response.ok)throw new Error(`Could not load ${n}.`);return response.json();}));lessons=[...data[0],...data[1]].sort((a,b)=>({programming:0,science:1,rehab:2,strength:3}[a.section]-{programming:0,science:1,rehab:2,strength:3}[b.section]));shelf=createBookshelf({data:data[20],esc,safeURL,sourceLink,routeTitle:r=>resolveRoute(r).title});sources=[...data[2],...data[3],...data[11],...data[13],...data[17],data[19].source,...shelf.sources];labCatalog=[...data[5],...data[6],...data[8]];curriculum=data[4];lessonById=new Map(lessons.map(l=>[l.id,l]));sourceById=new Map(sources.map(s=>[s.id,s]));practice=createPracticeLab({labs:[...data[5],...data[6],...data[8]],resources:data[7],labExtra:k=>shelf.labPanel(k),esc,getState:()=>state,save,sourceLink,lessonById,download});graduate=createGraduateCourses({courses:[data[9],data[10]],book:data[12],freeReading:k=>shelf.panel(k),freeSections:k=>shelf.sections(k),esc,getState:()=>state,save,toast,sourceLink,download});baseballCases=createBaseballCases({cases:[...data[14],...data[15],...data[16]],esc,getState:()=>state,save,toast,sourceLink,download});interview=createInterviewPrep({data:data[19],esc,getState:()=>state,save,toast,download});study=createStudyPlan({plan:data[18],lessons,units:graduate.units,labs:labCatalog,cases:baseballCases.catalog,esc,getState:()=>state,save,isReviewed,onOpen:openStudy});review=createReview({getState:()=>state,save,lessons:()=>lessons,record});resume=createResume({getState:()=>state,save,routeTitle:r=>resolveRoute(r).title});reader=createReaderTools({esc,getState:()=>state,save,toast,rerender:render,resolveRoute,getProgress:()=>({done:progressCounts().reviewed+graduate.counts().done,total:lessons.length+graduate.counts().total,label:'Foundation chapters + study units self-reviewed'}),download,getLegacyBookmarks:()=>lessons.filter(l=>record(l.id).bookmark).map(l=>({route:'lesson/'+l.id,title:l.title}))});let raw=null,kept=false;try{raw=localStorage.getItem(KEY);const saved=JSON.parse(raw||'null');if(saved)state=sanitizeProgress(saved);}catch{storageOK=false;if(raw){try{localStorage.setItem(KEY+'.unreadable-backup',raw);kept=true;}catch{}}}reader.mount();resume.mount();sync=createSync({getEnvelope:()=>({app:'baseball-performance-hub',version:1,exportedAt:new Date().toISOString(),data:state}),applyEnvelope:env=>{if(env?.app!=='baseball-performance-hub'||env.version!==1)throw new Error('Not a progress copy.');state=sanitizeProgress(env.data);save();render();},hasLocal:()=>!!raw,toast});window.addEventListener('hashchange',routeChanged);routeChanged();sync.mount();if(kept)toast('Saved progress could not be read. A copy was kept in this browser; import a backup to restore it.');}catch(err){main.innerHTML=`${heading('HUB NOT READY','The lesson library could not load.')}<p>${esc(err.message)}</p><p>Reload to try loading the lesson files again. If you are using the local edition, open it with its desktop launcher.</p><button class="button primary" onclick="location.reload()">Reload</button>`;console.error(err);}}
init();
